INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('amarte', 'Amarte', 'amarte', 'A', 'COMEDIA, ROMANCE', 96, 'Él vive en su propio universo. Ella es una famosa estrella de telenovelas que necesita desaparecer del suyo. Cuando se encuentran por accidente, lo que parece una mala idea se convierte en una escapada tan absurda como irresistible. Mientras huyen de la prensa, entre situaciones cada vez más fuera de lugar, momentos delirantes y una conexión que nadie vio venir, ambos descubren que escapar de la realidad puede ser mucho más divertido… y peligrosamente irresistible para el corazón. Pero cuando el mundo real vuelve a alcanzarlos, deberán decidir si ese encuentro fue sólo una fantasía perfecta o si vale la pena arriesgarse a vivir algo real.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Amarte/Es/amarte_poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Amarte/Es/amarte_header_movie_details_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Amarte/Es/6a750336bcc28-amarte.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('aniquilacion', 'Aniquilación', 'aniquilacion', 'A', 'THRILLER, ACCIÓN', 95, 'Cuando un escuadrón renegado de supersoldados genéticamente modificados escapa en el desierto, una francotiradora del Ejército, ruda y decidida, debe desatar el infierno para proteger a su pequeña hija.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Aniquilacion/Es/ANIQ_DESKTOP_P_ster_720x1022px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Aniquilacion/Es/ANIQ_DESKTOP_Header_flujo_de_compra_1440x900px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Aniquilacion/Es/6ac585128fb6d-aniquilacion.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033521', 'Clayface', 'clayface', 'C', 'TERROR, THRILLER', 108, 'De DC Studios, “Clayface” es un thriller de terror dirigido por James Watkins, protagonizado por Tom Rhys Harries en el papel principal del icónico villano favorito de culto de la galería de villanos de Gotham. El meteórico ascenso de Matt Hagen, de joven de las calles de Gotham a estrella de Hollywood, se ve trágicamente truncado cuando las acciones de un jefe del crimen local lo dejan horriblemente desfigurado. Abandonado por quienes lo rodean y sin nada que perder, Matt recurre a un tratamiento de vanguardia que milagrosamente le devuelve su apariencia anterior... pero que también altera de forma inesperada su percepción de la realidad, precipitándolo por un camino destructivo de venganza desmedida.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Clayface/Es/P_720X1022_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Clayface/Es/HMD_1440X900_7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Clayface/Es/6abd9302c9bb2-clayface.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033073', 'El Poder De La Red', 'el-poder-de-la-red', 'B', 'DRAMA, THRILLER', 112, 'Como complemento de la exitosa película La red social, el guion original de Sorkin se basa en los hechos que dieron origen al impactante reportaje del Wall Street Journal, Los archivos de Facebook. La película se inspira en la historia real de cómo Frances Haugen (Madison), una joven ingeniera de Facebook, recluta a Jeff Horwitz (White), un reportero del Wall Street Journal, para emprender un peligroso viaje que termina por revelar los secretos mejor guardados de la red social.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElPoderDeLaRed/Es/720x1022_25.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElPoderDeLaRed/Es/TSR_1440x900_V1_copia_2_.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElPoderDeLaRed/Es/6aa16953e44ac-poder-red.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('kraken-terror-en-lo-profundo', 'Kraken: Terror En Lo Profundo', 'kraken-terror-en-lo-profundo', 'B', 'THRILLER, SUSPENSO', 82, 'Cuando alguien revela la existencia de comportamientos anómalos y muertes masivas entre los salmones, la bióloga marina Johanne es enviada al fiordo más profundo de Noruega. Su misión consiste en investigar los posibles efectos negativos de un tratamiento experimental. Sin embargo, lo que comienza como una tarea rutinaria se convierte rápidamente en algo mucho más grave cuando dos jóvenes a bordo de una moto acuática sufren una muerte brutal e inexplicable, a la que siguen otros casos de cuerpos destrozados. Todo indica que esta tecnología ha despertado al mítico Kraken: un antiguo monstruo de múltiples tentáculos dispuesto a aplastar y devorar cualquier cosa que se mueva o se atreva a emitir sonido alguno.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/KrakenTerrorEnLoProfundo/Es/KRAKEN_poster_720X1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/KrakenTerrorEnLoProfundo/Es/1440x900_2.JPG', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/KrakenTerrorEnLoProfundo/Es/6a9883aa4bfe6-kraken.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033222', 'La Venganza Del Charro Negro', 'la-venganza-del-charro-negro', 'A', 'ANIMACIÓN', 94, 'Después de varios años, el temible Charro Negro regresa con un nuevo propósito: vengarse de Leo San Juan y cobrar una deuda que ha quedado pendiente. Para lograrlo, liberará a algunas de las criaturas y leyendas sobrenaturales que Leo ha enfrentado a lo largo de sus aventuras, obligándolo a reencontrarse con sus antiguos enemigos. Pero esta vez, el Charro Negro tiene un objetivo mucho más personal: su hermano, Nando. Mientras las leyendas se desatan y el peligro crece, Leo deberá proteger a su hermano y reunir nuevamente a sus amigos para descubrir el verdadero plan del Charro Negro. En una aventura que llevará al grupo al límite, Leo tendrá que enfrentarse una vez más a las criaturas de su pasado y descubrir que, para derrotar al Charro Negro, no solo tendrá que demostrar su valentía, sino luchar por aquello que más quiere.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaVenganzaDelCharroNegro/Es/720x1022_copia_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaVenganzaDelCharroNegro/Es/1440x900_69.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaVenganzaDelCharroNegro/Es/6aa88358db4b3-la-vengaza-del-charro-negro.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('tierra-de-mi-padre', 'Tierra De Mi Padre', 'tierra-de-mi-padre', 'A', 'DRAMA', 82, 'En el apogeo de la Guerra Fría, Patria se centra en la relación entre el escritor Thomas Mann y su hija Erika —actriz, escritora y conductora de rally— mientras se embarcan en un viaje por carretera en un crucero Buick negro a través de una Alemania en ruinas.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TierraDeMiPadre/Es/720x1022_24.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TierraDeMiPadre/Es/1440x900_55.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TierraDeMiPadre/Es/6a7cfbde56777-Fatherland.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033207', 'BTS WORLD TOUR ''ARIRANG'' IN BUENOS AIRES: EN VIVO', 'bts-world-tour-arirang-in-buenos-aires', 'A', 'CONCIERTO', 195, 'BTS WORLD TOUR ''ARIRANG'' IN BUENOS AIRES: EN VIVO', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/BTSWORLDTOURARIRANGINBUENOSAIRESENVIVO/Es/Poster_WEB_Desktop_720x1022px_36__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/BTSWORLDTOURARIRANGINBUENOSAIRESENVIVO/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_36__3.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033129', 'El Corazón De La Bestia', 'el-corazon-de-la-bestia', 'B', 'DRAMA, ACCIÓN', 101, 'Tras un aterrador accidente aéreo, el oficial de Fuerzas Especiales James Belmont (Brad Pitt) y su perro de combate, Odin, quedan varados en lo profundo de la naturaleza salvaje de Alaska. Juntos, se ven obligados a librar una brutal lucha por la supervivencia contra los elementos. Del aclamado cineasta David Ayer, Heart of the Beast es un intenso thriller de aventura que explora el vínculo irrompible entre un hombre y su mejor amigo mientras enfrentan su mayor batalla hasta ahora.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElCorazonDeLaBestia/Es/720x1022_24.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElCorazonDeLaBestia/Es/HOBT_A_1_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElCorazonDeLaBestia/Es/6a44173cccd16-HOTB_W8_1366x770_1.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033034', 'Resident Evil: Noche Cero', 'resident-evil-noche-cero', 'B15', 'TERROR, ACCIÓN', 94, 'De la mente del visionario cineasta Zach Cregger (Weapons, Barbarian) llega una emocionante —y aterradora— reinvención de la franquicia Resident Evil. En una historia completamente nueva, Resident Evil sigue a Bryan (Austin Abrams), un mensajero médico que, sin saberlo, se ve envuelto en una carrera por la supervivencia llena de acción y sin tregua cuando una noche fatídica y espantosa se convierte en un caos a su alrededor.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ResidentEvilNocheCero/Es/RE_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ResidentEvilNocheCero/Es/RE_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ResidentEvilNocheCero/Es/6a7cfa8bd1eab-RESIDENTEVIL.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032587', 'Coyote Vs Acme', 'coyote-vs-acme', 'A', 'COMEDIA, AVENTURA, LIVE ACTION ', 103, 'Tras décadas de explosiones por productos defectuosos y cansado de caídas al abismo, Wile E. Coyote decide demandar a ACME. El coyote más emblemático junto con el universo de los Looney Toones, está decidido a desmantelar un imperio y enfrentar a su implacable CEO (John Cena). Esta batalla, destruirá a una leyenda... o a una corporación. La película que ACME NO QUIERE QUE VEAS.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CoyoteVsAcme/Es/Poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CoyoteVsAcme/Es/Header_movie_details_1440x900px__8.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CoyoteVsAcme/Es/6a442a872bb67-CVA_Trailer_Zima_Dob_W8_1366x770.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033646', 'Cristiada', 'cristiada', 'B', 'DRAMA', 140, 'En el marco de los 100 años de la Guerra Cristera, hoy presentamos por primera vez en español la película Cristiada. Esta obra es mucho más que una crónica histórica de 1926 a 1929; nos cuenta la historia de un grupo apasionado de hombres y mujeres que deciden arriesgarlo todo por su familia, por el futuro de su país y, de manera fundamental, por defender su fe. Es, además, un poderoso relato sobre la transformación: seguimos los pasos de un líder inicialmente escéptico que, guiado por la convicción del joven José Sánchez del Río, termina al mando de todo el ejército cristero.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Cristiada/Es/Poster_WEB_Desktop_720x1022px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Cristiada/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_5.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-killing-castro', 'FICM Killing Castro', 'ficm-killing-castro', 'C', 'DRAMA, THRILLER', 101, 'En 1960, Fidel Castro llega a Estados Unidos para hablar ante la ONU. Malcolm X le invita a alojarse en Harlem, en el famoso Hotel Theresa. Inseguros de sus intenciones, el FBI, la CIA y la mafia intentan eliminarle por todos los medios.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMKillingCastro/Es/720x1022_copia_2__7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMKillingCastro/Es/1440x900_copia_2__12.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-to-hold-a-mountain', 'FICM To Hold a Mountain', 'ficm-to-hold-a-mountain', 'C', 'DOCUMENTAL', 105, 'En las remotas tierras altas de Montenegro, una madre y su hija, ambas pastoras, defienden con orgullo su montaña ancestral de la amenaza de convertirse en un campo de entrenamiento militar de la OTAN, lo que aviva recuerdos de la violencia que desgarró a su familia.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMToHoldAMountain/Es/to_hold_mountain.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMToHoldAMountain/Es/1440x900_2__1.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
