INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-burgundy', 'FICM Burgundy', 'ficm-burgundy', 'C', 'DOCUMENTAL', 90, 'La historia de los personajes más extraordinarios de Borgoña y una celebración del placer que define sus vidas.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMBurgundy/Es/burgundy.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMBurgundy/Es/1440x900_67.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
