INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-your-mother-your-mother-your-mother', 'FICM Your Mother, Your Mother, Your Mother', 'ficm-your-mother-your-mother-your-mother', 'A', 'DRAMA, THRILLER', 111, 'Latif, un sicario profundamente religioso, emprende un viaje desesperado por Houston para proteger a sus hijos tras la muerte de su esposa, por lo cual debe enfrentar fuerzas que lo acechan y creencias que amenazan con desmoronarse.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMYourMotherYourMotherYourMother/Es/720x1022_copia_2__7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMYourMotherYourMotherYourMother/Es/1440x900_copia_2__12.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-tinta', 'FICM Tinta', 'ficm-tinta', 'C', 'DRAMA', 116, 'La vida de Rupert Murdoch y su grupo de visionarios e inadaptados que tuvieron una idea para un nuevo tipo de periódico: uno que ofreciera a la gente lo que quería y cambiara el rostro del mundo en el que vivimos hoy.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMTinta/Es/720x1022_copia_2__7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMTinta/Es/1440x900_copia_2__12.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-the-man-i-love', 'FICM The Man I Love', 'ficm-the-man-i-love', 'C', 'ROMANCE, DRAMA', 97, 'Ambientada en la vibrante época de finales de los 80 en Nueva York, la película sigue a Jimmy George, un artista de performance del centro de la ciudad, en un momento extraordinario entre una grave enfermedad y la muerte, cuando, sin embargo, la belleza y el amor aún son posibles.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMTheManILove/Es/the_man_i_love_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMTheManILove/Es/1440x900_2__1.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-notre-salut', 'FICM Notre Salut', 'ficm-notre-salut', 'C', 'DRAMA', 158, 'Septiembre de 1940. Henri Marre llega solo a Vichy, Francia, mientras el régimen autoritario se instala. Arruinado, distanciado de su familia y con ejemplares de su manifiesto autopublicado, Notre Salut (Nuestra Salvación), este hombre de 49 años está decidido a asegurar lo que cree que le corresponde en la nueva administración.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMNotreSalut/Es/notre_salut_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMNotreSalut/Es/1440x900_2__1.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-queen-at-sea', 'FICM Queen at Sea', 'ficm-queen-at-sea', 'C', 'DRAMA', 121, 'Amanda y su padrastro, Martin, se enfrentan a un dilema moral que los divide. ¿Acaso la madre de Amanda, Leslie, quien padece demencia avanzada, ha perdido la capacidad de tomar decisiones cruciales en su propio beneficio? Y, de ser así, ¿quién es el responsable (su cónyuge, un hijo, una institución) de tomar esa decisión? A medida que Amanda y Martin se ven obligados a tomar decisiones cada vez más difíciles, las repercusiones se descontrolan.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMQueenatSea/Es/queen_at_sea.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMQueenatSea/Es/1440x900_2__1.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-el-ser-querido', 'FICM El Ser Querido', 'ficm-el-ser-querido', 'C', 'DRAMA', 135, 'El aclamado director de cine Esteban Martínez es una leyenda tanto por sus películas como por un pasado marcado por la violencia y los excesos. Para su nuevo proyecto, le ofrece un papel a su hija Emilia con el pretexto de ayudarla a relanzar su estancada carrera como actriz. Convivir en el set fomentará una cercanía que no han compartido en años, pero también reabrirá viejas heridas que nunca cicatrizaron.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMElSerQuerido/Es/720x1022_copia_2__7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMElSerQuerido/Es/1440x900_copia_2__12.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-heimsuchung', 'FICM Heimsuchung', 'ficm-heimsuchung', 'C', 'DRAMA', 118, 'Un panorama del último siglo de la historia alemana se despliega en una casa a orillas de un lago de Brandeburgo: un escenario para las historias de sus cambiantes propietarios y sus destinos entrelazados, marcados por acontecimientos históricos trascendentales: la República de Weimar, el Tercer Reich, la guerra y su fin, la Alemania Oriental y el periodo de la reunificación, todo ello mientras buscan un hogar y un lugar al que pertenecer.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMHeimsuchung/Es/720x1022_copia_2__7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMHeimsuchung/Es/1440x900_copia_12.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-el-bosque-salvaje', 'FICM El Bosque Salvaje', 'ficm-el-bosque-salvaje', 'A', 'ANIMACIÓN', 139, 'Después de que una bandada de cuervos secuestra a su hermano pequeño, la decidida adolescente Prue McKeel emprende una desesperada misión de rescate en un bosque encantado oculto justo a las afueras de Portland. Acompañada por Curtis, un compañero de clase tan torpe como leal, Prue lo arriesga todo mientras recorre un mundo habitado por bandidos, animales parlantes y figuras poderosas movidas por el dolor y la ambición.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMElBosqueSalvaje/Es/720x1022_copia_2__7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMElBosqueSalvaje/Es/1440x900_copia_2__12.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-versalles', 'FICM Versalles', 'ficm-versalles', 'B', 'COMEDIA', 92, 'Chema, un político mexicano en ascenso, tiene la presidencia al alcance de la mano. Pero cuando sus sueños se vienen abajo se refugia con su esposa en una antigua hacienda mientras pasa la tormenta. Lo que comienza como un exilio se convierte en una fantasía de poder absoluto. Desconectados de la realidad, Chema y Carmina se coronan rey y reina de un retorcido reino inventado.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMVersalles/Es/versalles_copia_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMVersalles/Es/1440x900_copia_2__13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-salon-de-belleza', 'FICM Salón de Belleza', 'ficm-salon-de-belleza', 'B15', 'DRAMA', 105, 'En una ciudad sin nombre, un salón de belleza se convierte en refugio para quienes han sido marginados, suspendidos entre la vida y la muerte. En su centro, el individuo cuida el lugar mientras el tiempo, la memoria y la imaginación se entrelazan. Cuando el mundo exterior irrumpe silenciosamente, belleza y muerte convergen en una meditación sobre la fragilidad de la existencia.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMSalondeBelleza/Es/salon_belleza_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMSalondeBelleza/Es/1440x900_52.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-reportaje', 'FICM Reportaje', 'ficm-reportaje', 'B', 'DOCUMENTAL', 103, 'Reportaje explora la relación entre la muerte y el periodismo de nota roja en la Ciudad de México. A través de fotógrafos, prensistas y voceadores, observa cómo la violencia se transforma en relato y cómo narrar permite habitar y trascender la muerte. En paralelo, un grupo de actores exinternos escenifica un crimen que resuena con sus propias historias, convirtiendo la representación en un acto de memoria y redención.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMReportaje/Es/reportaje_copia_2__1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMReportaje/Es/1440x900_copia_2__10.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-odisea-nacional', 'FICM Odisea Nacional', 'ficm-odisea-nacional', 'A', 'DOCUMENTAL', 92, 'Un viaje lírico y sugerente compuesto por microhistorias íntimas que exploran la profunda relación entre la arquitectura y la vida cotidiana, revelando experiencias humanas universales como la identidad, la desigualdad, la fe, la naturaleza, el arte y la necesidad de pertenecer. Una experiencia cinematográfica inmersiva sobre cómo los espacios nos moldean como seres humanos y el profundo impacto que tienen en nuestras vidas.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMOdiseaNacional/Es/odisea_nacional_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMOdiseaNacional/Es/1440x900_copia_2__10.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033627', 'Godzilla Minus Zero', 'godzilla-minus-zero', 'A', 'CIENCIA FICCIÓN', 135, 'GODZILLA MINUS ZERO retoma la historia en 1949, dos años después de los turbulentos acontecimientos de Godzilla Minus One, y continúa la historia de la familia Shikishima mientras enfrentan una nueva catástrofe. Como proyecto filmado para IMAX, GODZILLA MINUS ZERO fue filmada con cámaras digitales de alta definición certificadas por IMAX y optimizada en sonido e imagen de manera única para pantallas IMAX. Los fans podrán ver a Godzilla llevado a nuevas y terroríficas alturas, haciendo de GODZILLA MINUS ZERO un verdadero evento cinematográfico imperdible.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GodzillaMinusZero/Es/Poster_720x1022_Godzilla_5ago1_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GodzillaMinusZero/Es/Header_movie_1440x900_Still_Godzilla_5ago_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GodzillaMinusZero/Es/6a7ccff3283f2-godzilla-minus-zero.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033355', 'El Bosque Salvaje: Wildwood', 'el-bosque-salvaje-wildwood', 'A', 'ANIMACIÓN', 132, 'Después de que su pequeño hermano es secuestrado por una parvada de cuervos, la audaz adolescente, Prue, inicia una desesperada misión de rescate hacia el Bosque Salvaje acompañada únicamente por su torpe pero leal compañero de clase, Curtis. Prue navega por un mundo de animales parlantes, bandidos y poderosas figuras impulsadas por el duelo y la ambición. Mientras los amigos se ven arrastrados a un conflicto que amenaza el equilibrio del bosque mismo, Prue debe descubrir la fuerza y la fe que nunca supo que poseía. Si quiere salvar a su hermano y proteger el frágil futuro de Wildwood, tendrá que arriesgarlo todo.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElBosqueSalvajeWildwood/Es/Wildwood_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElBosqueSalvajeWildwood/Es/Header_movie_details_1440x900__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElBosqueSalvajeWildwood/Es/6ab4000547426-wildwood.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-hombre-al-agua', 'FICM Hombre al Agua', 'ficm-hombre-al-agua', 'B', 'COMEDIA, DRAMA', 120, 'Camilo, un salvavidas cubano, salva de morir ahogado a Abel, un empresario mexicano. Agradecido, Abel lleva a Camilo a México; allí, se casa con Juana, hija de Abel, y tienen un hijo. Sin embargo, Camilo pronto descubre que su nueva vida forma parte de un plan maquiavélico de manipulación y control urdido por Abel.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMHombrealAgua/Es/hombre_agua_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMHombrealAgua/Es/1440x900_52.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-la-gradiva', 'FICM La Gradiva', 'ficm-la-gradiva', 'C', 'DRAMA', 145, 'Un grupo de estudiantes de preparatoria franceses viaja a Nápoles en una excursión escolar para descubrir las ruinas de Pompeya y los cuerpos petrificados por el Vesubio. Allí, se ven envueltos en un vertiginoso descenso. Uno a uno, son arrastrados por el deseo y la ira, hasta que se entregan por completo a ellos.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMLaGradiva/Es/la_gradiva_copia_2__1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMLaGradiva/Es/1440x900_63.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-marcos-otro-mundo-es-posible', 'FICM Marcos. Otro Mundo es Posible', 'ficm-marcos-otro-mundo-es-posible', 'A', 'DOCUMENTAL', 131, 'En 1994, un hombre sin rostro se volvió el rostro más visible de una rebelión indígena que sorprendió al mundo. A través de la figura del Subcomandante Marcos, este documental se adentra en la lucha de los pueblos zapatistas que, más de treinta años después, siguen construyendo en las montañas de Chiapas una forma propia de resistir y vivir.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMMarcosOtroMundoesPosible/Es/marcos_otro_mundo_copia_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMMarcosOtroMundoesPosible/Es/1440x900_64.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-adieu-monde-cruel', 'FICM Adieu Monde Cruel', 'ficm-adieu-monde-cruel', 'C', 'ROMANCE, DRAMA', 93, 'Otto Vidal, de 14 años, desaparece tras escribir una carta para sus compañeros de clase en la que anuncia su suicidio. Si bien todos lo dan por muerto, Léna, una chica de su instituto, lo ve una noche vagando por las calles de la ciudad.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMAdieuMondeCruel/Es/adieu_monde_copia_2__1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMAdieuMondeCruel/Es/1440x900_63.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-arima', 'FICM Arima', 'ficm-arima', 'B', 'DRAMA', 76, 'La vida de cuatro mujeres y una niña se ve alterada con la inesperada llegada de dos forasteros. Uno de ellos huye del otro, se esconde por el pueblo como un ser huidizo, fantasmagórico y de dudosa existencia. El otro, un hombre herido y con un arma, perturbará de diferentes formas la vida de las mujeres. Todo ello se mueve entre lo real y lo imaginario, la pesadilla y el sueño, el miedo y el deseo, en una historia impregnada de misterio.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMArima/Es/arima.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMArima/Es/1440x900_52.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-cenizas-en-la-boca', 'FICM Ceniza en la Boca', 'ficm-cenizas-en-la-boca', 'B', 'DRAMA', 102, 'Lucila abandona México con su hermano menor para reunirse con su madre en Madrid, quien se había marchado unos años antes en busca de un futuro mejor. Al llegar, la cruda y asfixiante realidad que les espera resulta mucho más dura de lo que Lucila había imaginado. Aun así, está decidida a sacar el máximo provecho de esta nueva y frágil vida.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMCenizaenlaBoca/Es/ceniza_boca_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMCenizaenlaBoca/Es/1440x900_52.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-cortometraje-mexicano-de-ficcion-programa-1', 'FICM Cortometraje Mexicano de Ficción Programa 1', 'ficm-cortometraje-mexicano-de-ficcion-programa-1', 'B15', 'DRAMA', 108, 'Cortometrajes que forman parte de la Selección Oficial del 24° FICM.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMCortometrajeMexicanodeFiccionPrograma1/Es/cortometraje_mx_ficcion_1_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMCortometrajeMexicanodeFiccionPrograma1/Es/1440x900_copia_10.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-la-Ilusion-de-un-verano-sin-fin', 'FICM La Ilusión de un Verano Sin Fin', 'ficm-la-Ilusion-de-un-verano-sin-fin', 'A', 'DOCUMENTAL', 94, 'Durante 25 años, la fotógrafa Alessandra Sanguinetti documenta la vida de Guillermina y Belinda, dos primas inseparables que crecen en la Pampa argentina. A través de imágenes de archivo y registros de video, la película reflexiona sobre el paso del tiempo, la amistad y la transformación de la vida adulta.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMLaIlusiondeunVeranoSinFin/Es/la_ilusion_verano.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMLaIlusiondeunVeranoSinFin/Es/1440x900_2__1.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-traces-of-home', 'FICM Traces of Home', 'ficm-traces-of-home', 'C', 'DOCUMENTAL', 93, 'La cineasta Colette Ghunim emprende viajes junto a sus padres para encontrar las casas ancestrales de las que se vieron obligados a huir cuando eran niños en México y Palestina. El deseo inicial de Colette de sanar la desconexión con sus culturas y sus padres revela una búsqueda interior para hallar el hogar dentro de sí misma.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMTracesofHome/Es/traces_home_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMTracesofHome/Es/1440x900_52.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-the-lion-queen', 'FICM The Lion Queen', 'ficm-the-lion-queen', 'C', 'DOCUMENTAL', 87, 'El divorcio del siglo XX convirtió a Jocelyne Wildenstein, conocida como la Mujer Gato, en una obsesión de la prensa sensacionalista de los 90, y puso en el ojo público al imperio de los Wildenstein. Este documental explora la vida de una mujer marcada por una riqueza y un escrutinio extraordinarios y ofrece una mirada reveladora del precio de la fama y la fortuna.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMTheLionQueen/Es/the_lion_queen.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMTheLionQueen/Es/1440x900_2__1.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('the-story-of-documentary-film', 'FICM The Story of Documentary Film', 'the-story-of-documentary-film', 'C', 'DOCUMENTAL', 120, 'Esta serie revisa la historia del documental desde sus inicios hasta la actualidad. También reexamina clásicos del género, nuevos e impactantes descubrimientos y obras olvidadas de todo el mundo. Estructurada cronológicamente, pero intercalada con secciones temáticas independientes, la serie desafía las ideas preconcebidas sobre qué es el documental.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMTheStoryOfDocumentaryFilm/Es/the_story_documentary_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMTheStoryOfDocumentaryFilm/Es/1440x900_2__1.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-petardos-magnolias', 'FICM Petardos & Magnolias', 'ficm-petardos-magnolias', 'B15', 'DRAMA', 105, 'Vera, de 18 años y una de las mejores futbolistas de la Prepa 8 de la UNAM, sueña con convertirse en una estrella del futbol femenil, pese a la oposición de su padre. Todo cambia cuando conoce a Alan, integrante del grupo de choque de su preparatoria. Al enamorarse de él, Vera descubre un mundo peligroso donde tendrá que enfrentar las consecuencias de sus decisiones y entender que el amor también tiene un precio.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMPetardosMagnolias/Es/petardos_magnolias_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMPetardosMagnolias/Es/1440x900_copia_13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-paper-tiger', 'FICM Paper Tiger', 'ficm-paper-tiger', 'C', 'DRAMA', 115, 'En París, el estudiante estadounidense Matthew conoce a dos hermanos con quienes comparte la pasión por el cine. Cuando sus padres se marchan al campo, Matthew se muda con ellos y descubre que su relación va más allá del cariño fraternal habitual.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMPaperTiger/Es/paper_tiger_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMPaperTiger/Es/1440x900_52.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033376', 'Street Fighter', 'street-fighter', 'B', 'DRAMA, ACCIÓN', 119, 'Ambientada en 1993, los distanciados luchadores callejeros Ryu (Andrew Koji) y Ken Masters (Noah Centineo) se ven obligados a volver al combate cuando la misteriosa Chun-Li (Callina Liang) los recluta para el próximo Torneo Mundial de Luchadores: un brutal enfrentamiento de puños, destino y furia. Pero detrás de esta batalla real se esconde una conspiración mortal que los obliga a enfrentarse entre sí y a los demonios de su pasado. Y si no lo hacen, ¡GAME OVER!', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StreetFighter/Es/sf_desktop_poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StreetFighter/Es/sf_desktop_header_movie_details_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StreetFighter/Es/6a870c70166c5-street-fighter.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033634', 'La Caída De La Ballena', 'la-caida-de-la-ballena', 'B', 'SUSPENSO', 106, 'Tras la muerte de su padre (Josh Brolin), Jay Gardiner (Austin Abrams) se sumerge en la costa central de California en busca de sus restos, pero es tragado por un enorme cachalote. Atrapado en el interior del animal y con solo una hora de oxígeno restante, Jay descubre que las lecciones que su padre le enseñó podrían ser la clave para sobrevivir y escapar.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaCaidaDeLaBallena/Es/19_Poster_720x1022px__5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaCaidaDeLaBallena/Es/4_Header_movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaCaidaDeLaBallena/Es/6abd9611801cc-whalefall.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033240', 'El Laberinto Del Fauno', 'el-laberinto-del-fauno', 'B15', 'DRAMA, FANTASÍA', 118, 'Con motivo de su 20.º aniversario, El laberinto del fauno, del visionario cineasta Guillermo del Toro, es una cinta de fantasía oscura ganadora del Premio de la Academia®, ambientada en la España de 1944. Mientras las fuerzas fascistas estrechan su control tras la Guerra Civil española, la joven Ofelia (Ivana Baquero) es llevada a un remoto puesto militar bajo el mando de su cruel padrastro (Sergi López). En medio de la brutalidad de la guerra, Ofelia descubre un laberinto oculto y se encuentra con un misterioso fauno que afirma que ella es una princesa perdida. Para recuperar su trono, deberá completar tres peligrosas pruebas que pondrán a prueba su valentía y su espíritu. A medida que la realidad y la fantasía se entrelazan, el viaje de Ofelia se convierte en una poderosa exploración de la inocencia, la resistencia y el poder perdurable de la imaginación frente a una oscuridad inimaginable.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElLaberintoDelFauno/Es/Poster_WEB_Desktop_720x1022px_43__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElLaberintoDelFauno/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_45__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElLaberintoDelFauno/Es/6ac6a503c38ac-el-laberinto-fauno.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033029', 'Verity: La Sombra De Un Engaño', 'verity-la-sombra-de-un-engano', 'B15', 'SUSPENSO', 117, 'Basada en la exitosa novela de Colleen Hoover, este seductor thriller psicológico sigue a la reconocida autora Verity Crawford (Anne Hathaway) y a Lowen Ashleigh (Dakota Johnson), una escritora en apuros que se muda a la remota mansión Crawford para escribir como ghostwriter para Verity. Después de que Lowen descubre lo que parecen ser las escalofriantes notas autobiográficas de Verity, lucha con las perturbadoras y retorcidas confesiones sobre el esposo de Verity, Jeremy (Josh Hartnett), y le resulta difícil separar la ficción de la realidad, la manipulación de la atracción, y la oportunidad de la obsesión.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/VerityLaSombraDeUnEngano/Es/VRTY_2026_Desktop_Cinepolis_Poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/VerityLaSombraDeUnEngano/Es/VRTY_2026_Desktop_Cinepolis_HeaderMovieDetails_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/VerityLaSombraDeUnEngano/Es/6a91ece8785e6-verity.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033108', 'Digger', 'digger', 'B15', 'COMEDIA, DRAMA', 129, 'El cineasta ganador del Oscar Alejandro G. Iñárritu regresa con su película original DIGGER, protagonizada por Tom Cruise en el papel principal. El hombre más poderoso del mundo emprende una frenética misión para demostrar que es el salvador de la humanidad antes de que el desastre que ha desatado destruya todo.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Digger/Es/720x1022_28.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Digger/Es/HMD_1440X900_8.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Digger/Es/6a9883ec5b261-digger.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033358', 'Madre Siniestra', 'madre-siniestra', 'B', 'HORROR PSICOLÓGICO', 93, 'Bela, una niña de 8 años que vive en un hogar con problemas matrimoniales, se enfrenta a una entidad siniestra que sale de su clóset. La presencia, a quien ella llama "Otra Mamá", se vuelve cada vez más amenazante para ella y su familia.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MadreSiniestra/Es/20_Po_ster_720x1022px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MadreSiniestra/Es/15_Header_Movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MadreSiniestra/Es/6a8f6e14b4a58-madre-siniestra.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033356', 'La Isla De Las Muñecas', 'la-isla-de-las-munecas', 'B', 'TERROR', 80, 'Cuenta la leyenda de este lugar, que cerca de las chinampas de Don Julián una joven se ahogo entre los lirios y ahi su cuerpo fue encontrado.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaIslaDeLasMunecas/Es/IDLM_Poster_720X1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaIslaDeLasMunecas/Es/IDLM_Header_Movie_details_1440X900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaIslaDeLasMunecas/Es/6ab437a2ae697-isla-munecas.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033429', 'Súper Canino', 'super-canino', 'A', 'ANIMACIÓN, AVENTURA, FAMILIAR', 95, 'Danny es un niño tímido cuya vida cambia cuando su querido perro, Charlie, es abducido por extraterrestres y regresa con superpoderes, convertido en el famoso Súper Canino. Pero Puddy, un gato con poderes extraordinarios, está decidido a conquistar a la humanidad junto con su pandilla felina. Ahora, Danny y Charlie deberán superar sus diferencias y unir fuerzas para detener sus diabólicos planes.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/SuperCanino/Es/Poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/SuperCanino/Es/Header_movie_details_1440x900px__8.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/SuperCanino/Es/6abd5d97dcf3d-super-canino.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033068', 'Tu Nombre', 'tu-nombre', 'A', 'ANIMACIÓN', 107, 'Mitsuha, una adolescente que vive en un pequeño pueblo de Japón, sueña con escapar de su vida cotidiana y conocer una ciudad llena de oportunidades. Taki, un joven que vive en Tokio, lleva una vida completamente diferente. Un día, ambos comienzan a intercambiar cuerpos misteriosamente mientras duermen, despertando cada uno en la vida del otro. Aunque al principio intentan comprender y controlar este extraño fenómeno, poco a poco desarrollan un vínculo especial a través de mensajes y recuerdos. Sin embargo, cuando el intercambio desaparece inesperadamente, Taki emprende una búsqueda para encontrar a Mitsuha y descubrir la verdad detrás de su conexión, enfrentándose a un misterio que trasciende el tiempo y el espacio. Revive esta historia 10 años despues de su estreno en salas de cine.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TuNombre/Es/Poster_WEB_Desktop_720x1022px_35__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TuNombre/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_35__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TuNombre/Es/6ac6a52bbd523-your-name.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033367', 'Hope: El Primer Impacto ', 'hope-el-primer-impacto', 'B15', 'ACCIÓN', 157, 'Un misterioso descubrimiento se realiza en las afueras de la remota ciudad del puerto. Los residentes se encuentran en una lucha desesperada por la supervivencia contra algo que nunca antes habían encontrado.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HopeElPrimerImpacto/Es/HOPE_Cinepolis_MX_DESKTOP_720_x_1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HopeElPrimerImpacto/Es/HOPE_Cinepolis_MX_DESKTOP_1440_x_900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HopeElPrimerImpacto/Es/6aa87c469b3df-hope-el-primer-impacto.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033274', 'Un Mal Partido ', 'un-mal-partido', 'A', 'COMEDIA', 91, 'Guillermo Gómez, un padre sobreprotector, controlador y algo neurótico de casi cincuenta años, vive convencido de que su misión en la vida es mantener a salvo a su hija Mía, una joven de 19 años, alegre, impulsiva y llena de vida. Su relación es tan cercana que casi parece una sociedad secreta: “Somos un pinche equipazo”, se repiten como mantra. Pero cuando Guillermo descubre que Mía está saliendo con Martín, un veinteañero excéntrico, improvisado, un tipo torpe, pero encantador que le cae bien a todos, y que además estudia “Psicología para perros” sin universidad, su mundo se derrumba. “Un Mal Partido” es una comedia familiar llena de situaciones absurdas y entrañables, donde el miedo a perder el amor se convierte en una oportunidad para reencontrarlo. Una historia sobre el paso del tiempo, los límites del amor paterno y la dulce, dolorosa tarea de dejar ir.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/UnMalPartido/Es/19_Poster_720x1022px__5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/UnMalPartido/Es/14_Header_Movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/UnMalPartido/Es/6aa884902ed00-un-mal-partido.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033370', 'El Árbol Mágico', 'el-arbol-magico', 'A', 'FANTASÍA, FAMILIAR', 110, 'Una familia moderna debe mudarse al campo, sin wifi ni electricidad. Por lo tanto, los niños deben conectarse con la naturaleza que los rodea. Al explorar su nuevo hogar, descubren un árbol mágico con residentes extraordinarios y excéntricos. A través de las alegrías y los desafíos de cada una de sus aventuras, la familia aprende a reconectarse y a valorarse mutuamente por primera vez en años.​', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElArbolMagico/Es/720_copia_2_.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElArbolMagico/Es/Header_Movie_Details_1440x900_MFT_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElArbolMagico/Es/6aa32667e9b00-arbol-magico.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033637', 'Sacrificio: Los Elegidos', 'sacrificio-los-elegidos', 'B', 'AVENTURA, ACCIÓN', 100, 'Un evento benéfico repleto de estrellas se convierte en un caos cuando un grupo radical se cuela en él en busca de un artefacto místico relacionado con una antigua profecía.​', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/SacrificioLosElegidos/Es/Poster_720x1022_S_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/SacrificioLosElegidos/Es/Header_Movie_Details_1440x900_S_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/SacrificioLosElegidos/Es/6abd611e062ca-sacrificio.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032858', 'El Final', 'el-final', 'A', 'DRAMA', 87, 'Un grupo de recién graduados sale a dar un paseo nocturno en busca de comida, con la esperanza de disfrutar de una última noche juntos antes de que sus caminos se separen. Amontonados en un Jeep Cherokee, acabarán adentrándose en un infierno interminable de dos carriles, rodeado de horrores incalculables y fuerzas cósmicas inexplicables. Un ingenioso debut que utiliza una pesadillesca carretera sin fin para hablar de la espeluznante transición a la edad adulta.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElFinal/Es/P_ster_720x1022px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElFinal/Es/Header_Movie_details_1440x900px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElFinal/Es/6a86639cbe179-el-final.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033122', 'Always Lalisa', 'always-lalisa', 'A', 'DOCUMENTAL', 100, 'Always Lalisa es un documental de larga duración que sigue a la superestrella mundial LISA durante un año transformador lejos de Blackpink, el fenómeno del K-pop que la convirtió en una de las artistas más reconocidas del mundo. Mientras el grupo se toma un descanso, LISA se lanza al primer capítulo de verdad de su carrera solista, enfrentándose a la pregunta de quién es ella más allá de Blackpink.La película sigue a LISA mientras escribe, graba y lanza su primer álbum solista, Alter Ego, hace su debut como actriz en la tercera temporada de The White Lotus y se prepara para su primera gran presentación solista en el Festival de Música de Coachella de 2025. LISA, que nació y creció en Tailandia, se fue de casa a los catorce años para recibir capacitación en el exigente sistema del K-pop de Corea del Sur, y finalmente alcanzó el estrellatomundial. Pero abrirse camino por su cuenta, sobre todo en el mercado musical occidental, conlleva nuevas presiones, un escrutinio implacable y el reto de redefinirse a sí misma según sus propios términos.Íntima, emotiva y reveladora, Always Lalisa muestra a una artista en una encrucijada, documentando un año de riesgos, reinvención y autodescubrimiento mientras LISA empieza a definir no solo su próximo capítulo, sino también la mujer y la artista en la que quiere convertirse.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/AlwaysLalisa/Es/Poster_WEB_Desktop_720x1022px_33_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/AlwaysLalisa/Es/1440x900_61.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/AlwaysLalisa/Es/6aa8783f1eeec-Sweet-Lalisa.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032982', 'Avengers: Endgame Bonus', 'avengers-endgame-bonus', 'B', 'ACCIÓN, CIENCIA FICCIÓN', 191, 'Tras los devastadores sucesos de Avengers: Infinity War, el universo está en ruinas pero de los que quedan, los Avengers se unirán una vez más para deshacer la destrucción de Thanos y restaurar el orden del mundo.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/AvengersEndgameBonus/Es/19_Poster_720x1022px__5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/AvengersEndgameBonus/Es/4_Header_movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/AvengersEndgameBonus/Es/6a95930ba5241-avengers-endgame-encore.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
