INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033317', 'HCF: HYBE CHEERING PARTY ', 'hcf-hybe-cheering-party', 'A', 'CONCIERTO', 60, '¡El entusiasmo por los artistas de HYBE llega a los cines! ¡Canta con tus artistas favoritos de HYBE en 3D! Se acerca una proyección única, tipo juego, en la que los fans podrán corear consignas y agitar sus barras luminosas mientras ven los videos musicales de BTS, SEVENTEEN, TOMORROW X TOGETHER, ENHYPEN, LE SSERAFIM, &TEAM, BOYNEXTDOOR, TWS, ILLIT, KATSEYE, aoen, CORTIS y SANTOS BRAVOS en pantalla grande. ¡Únete a esta celebración inolvidable llena de música variada, la energía apasionada de los fans y una deslumbrante ola de Light Sticks!', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFHYBECHEERINGPARTY/Es/Poster_WEB_Desktop_720x1022px_38__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFHYBECHEERINGPARTY/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_38__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFHYBECHEERINGPARTY/Es/6ac6a58445109-hybe-fest.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033311', 'HCF: SEVENTEEN WORLD TOUR NEW', 'hcf-seventeen-world-tour-new', 'A', 'CONCIERTO', 102, 'Para celebrar el décimo aniversario de su debut, SEVENTEEN se lanza a una gira mundial impulsados por su determinación de empezar de cero, tal como lo indica el título NEW_ Con su presencia escénica sin igual y su energía explosiva, SEVENTEEN vuelve a demostrar su potencial ilimitado. ¡Vive la intensidad del concierto —rebosante del encanto único de cada miembro— directamente en la pantalla grande!', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFSEVENTEENWORLDTOURNEW/Es/Poster_WEB_Desktop_720x1022px_41__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFSEVENTEENWORLDTOURNEW/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_42__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFSEVENTEENWORLDTOURNEW/Es/6ac6a5d8f18ac-hybe-fest.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033313', 'HCF: TOMORROW X TOGETHER WORLD TOUR ACT: TOMORROW', 'hcf-tomorrow-x-together-world-tour-act', 'A', 'CONCIERTO', 97, 'Como estrellas brillantes, la cuarta gira mundial de TOMORROW X TOGETHER, ACT: TOMORROW, se desarrolla como un viaje deslumbrante hacia el mañana que prometieron juntos. Desde su hermosa narrativa hasta la impresionante producción y las impactantes presentaciones en vivo que cautivaron a los MOA de todo el mundo, ¡vive la energía envolvente de la espectacular gira mundial de TOMORROW X TOGETHER en la pantalla grande!', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFTOMORROWXTOGETHERWORLDTOURACTTOMORROW/Es/Poster_WEB_Desktop_720x1022px_40__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFTOMORROWXTOGETHERWORLDTOURACTTOMORROW/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_40__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFTOMORROWXTOGETHERWORLDTOURACTTOMORROW/Es/6ac6a5c1aa1bc-hybe-fest.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033315', 'HCF: ENHYPEN WORLD TOUR BLOOD SAGA ', 'hcf-enhypen-world-tour-blood-saga', 'A', 'CONCIERTO', 101, 'La gira mundial actual de ENHYPEN, BLOOD SAGA, sigue cautivando al público de todo el mundo. Revive el inolvidable concierto en Seúl que marcó el inicio de la BLOOD SAGA, donde cobra vida una fascinante fantasía oscura. La coreografía intensa y sincronizada de los integrantes y una escenografía espectacular e impresionante surgen de entre el resplandor rojo y la oscuridad profunda. ¡Disfruta del sonido intenso al estilo de una banda y del universo vampírico sin igual que solo ENHYPEN puede ofrecerte en los cines!', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFENHYPENWORLDTOURBLOODSAGA/Es/Poster_WEB_Desktop_720x1022px_39__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFENHYPENWORLDTOURBLOODSAGA/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_39__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFENHYPENWORLDTOURBLOODSAGA/Es/6ac6a59c88ef8-hybe-fest.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033210', 'BTS WORLD TOUR ''ARIRANG'' IN SÃO PAULO: EN VIVO', 'bts-world-tour-arirang-in-sao-paulo', 'A', 'CONCIERTO', 195, 'BTS WORLD TOUR ''ARIRANG'' IN SÃO PAULO: LIVE VIEWING ¡Vive la experiencia BTS WORLD TOUR ''ARIRANG'' en cines de todo el mundo, transmitida desde São Paulo, Brasil! Como colofón de su gira por Latinoamérica, este concierto monumental llevará directamente a la pantalla grande toda la energía explosiva del estadio repleto de Brasil. Las transmisiones en algunos territorios están programadas en horario diferido para adaptarse a los husos horarios locales.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/BTSWORLDTOURARIRANGINSAOPAULO/Es/Poster_WEB_Desktop_720x1022px_37__6.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/BTSWORLDTOURARIRANGINSAOPAULO/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_37__6.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033246', 'Rammstein - Live in Mexico City', 'rammstein-live-in-mexico-city', 'A', 'EN VIVO', 110, 'Rammstein - Live in Mexico City', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/RammsteinLiveinMexicoCity/Es/Poster_WEB_Desktop_720x1022px_38__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/RammsteinLiveinMexicoCity/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_38__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/RammsteinLiveinMexicoCity/Es/6ac6a6a81fbf4-rammstein.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033082', 'Duna: Parte Tres', 'duna-parte-3', 'A', 'DRAMA, THRILLER, ACCIÓN', 168, 'Warner Bros. Pictures y Legendary Pictures presentan «Dune: Parte Tres», que pone un final impresionante a la épica trilogía del cineasta Denis Villeneuve, nominado a los premios Óscar.«Dune: Parte Tres» se desarrolla casi dos décadas después de que Paul Atreides tomara el control del Imperio. Ahora, convertido en un emperador despiadado, Paul debe afrontar las consecuencias de su reinado mientras regresan antiguos aliados, surgen nuevas y aterradoras amenazas y la traición acecha en cada sombra.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/DunaParte3/Es/dune_3_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/DunaParte3/Es/dune_3_1440x900_copia.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033682', 'Stray Kids World Tour <RUN IT> LIVE VIEWING', 'stray-kids-world-tour-run-it-live-viewing', 'A', 'CONCIERTO', 195, 'Por primera vez, Stray Kids presenta una transmisión especial en vivo de «Stray Kids World Tour » desde el Tokyo Dome en cines de todo el mundo. Fiel al título de la gira, refleja el impulso del grupo por adentrarse en mundos más grandes y subir a escenarios más audaces. Los ocho miembros (Bang Chan, Lee Know, Changbin, Hyunjin, HAN, Felix, Seungmin e I.N) desatan una energía imparable a través de coreografías explosivas y voces potentes, llevando la experiencia en vivo a su punto más álgido. Su presentación empieza con «Hall of Fame», una canción que expresa la ambición de Stray Kids de escribir su propia historia, trazando su crecimiento musical desde el principio hasta donde están ahora. La producción se enriquece aún más con montajes escénicos dinámicos, toques de espectáculos tradicionales coreanos y una iluminación láser espectacular, todo diseñado para que el público —tanto en el estadio como en el cine— se ponga de pie, cante, baile y celebre junto con los artistas. Grabado en vivo desde Tokio y transmitido a cines de todo el mundo, este evento de proyección en vivo te permite a ti, como parte de STAY, disfrutar de la magnitud, el espectáculo y la energía pura del show en vivo de Stray Kids —todos juntos, en la pantalla grande.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StrayKidsWorldTourRUNITLIVEVIEWING/Es/StrayKids_LiveViewing_720x1022_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StrayKidsWorldTourRUNITLIVEVIEWING/Es/StrayKids_LiveViewing_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StrayKidsWorldTourRUNITLIVEVIEWING/Es/6ad112c94c215-Stray_Kids_World_Tour_30_Trailer_SPANISH_W8_1366x770.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033701', 'Fiesta Pagana', 'fiesta-pagana', 'A', 'BIOPIC', 128, 'A finales de los años ochenta, un grupo de jóvenes de barrio decide desafiar todas las reglas y perseguir un sueño que parecía imposible: fusionar la fuerza del heavy metal con la magia del folk celta. Lo que comenzó como la aventura de unos amigos acabó convirtiéndose en un fenómeno que revolucionó el rock en español y cambió sus vidas para siempre. FIESTA PAGÄNA es una película de ficción inspirada en la extraordinaria historia de Mägo de Oz. Comedia, musical, drama y ópera rock, explora lo que sucede cuando los sueños se cumplen y el éxito empieza a cobrar su precio. Sus canciones se convirtieron en la banda sonora de varias generaciones y en himnos que todavía hoy cantan millones de personas a ambos lados del Atlántico. Porque más de tres décadas después, la música y la leyenda de Mägo de Oz siguen más vivas que nunca. Inspirada en hechos reales. En cuáles depende de a qué miembro de la banda se le pregunte.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FiestaPagana/Es/FiestaPagana_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FiestaPagana/Es/FiestaPagana_1440x900_2.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033192', 'Vértigo 2: Punto Muerto', 'vertigo-2-punto-muerto', 'B', 'SUSPENSO', 98, 'Durante una peligrosa escalada en el monte Kwan, en Tailandia, dos escaladoras quedan atrapadas a miles de metros sobre el suelo, donde las alturas vertiginosas, la exposición extrema y las pocas probabilidades de sobrevivir convierten cada instante en una lucha por mantenerse con vida.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Vertigo2PuntoMuerto/Es/Poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Vertigo2PuntoMuerto/Es/Header_movie_details_1440x900px__8.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Vertigo2PuntoMuerto/Es/6a98833208c7b-vertigo-2.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('volcan-fuego-bajo-tierra', 'Volcán: Fuego Bajo Tierra', 'volcan-fuego-bajo-tierra', 'B', 'SUSPENSO', 107, 'VOLCÁN: FUEGO BAJO TIERRA es un intenso relato de desastre natural que combina espectáculo y drama humano al seguir a una comunidad enfrentada a la inminente erupción de un volcán que amenaza con arrasarlo todo. A medida que la tierra se abre y el peligro se vuelve inevitable, la historia se adentra en las decisiones límite, los vínculos que se tensan y los sacrificios que surgen cuando el tiempo se agota. Entre la furia de la naturaleza y la fragilidad humana, la película plantea una lucha no solo por sobrevivir, sino por encontrar sentido en medio del caos que emerge desde las profundidades.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/VolcanFuegoBajoTierra/Es/720X1022_POSTER.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/VolcanFuegoBajoTierra/Es/1440x900_57.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/VolcanFuegoBajoTierra/Es/6a1f311f3180f-volcan.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('shaun-el-cordero-el-monstruo-de-moss-y-bottom', 'Shaun, El Cordero: El Monstruo De Mossy Bottom', 'shaun-el-cordero-el-monstruo-de-moss-y-bottom', 'A', 'COMEDIA, ANIMACIÓN, AVENTURA', 80, 'En la víspera de Halloween en la granja Mossy Bottom, la emoción se convierte en decepción cuando el torpe granjero arruina el huerto de calabazas. Shaun intenta arreglarlo con experimentos científicos, pero las cosas se complican cuando una bestia salvaje aparece en el bosque.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ShaunElCorderoElMonstruoDeMossyBottom/Es/CINEPOLISAPP_P_ster_720x1022px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ShaunElCorderoElMonstruoDeMossyBottom/Es/CINEPOLISDESKTOP_Header_Movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ShaunElCorderoElMonstruoDeMossyBottom/Es/6a8f67c4db1c4-shaun-el-cordero.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('la-ultima-semana-de-jesus', 'La Última Semana De Jesús', 'la-ultima-semana-de-jesus', 'A', 'DRAMA', 81, 'Jesús entra en Jerusalén consciente de que ha comenzado la última semana de su vida. Mientras las autoridades políticas y religiosas se preparan para silenciarlo, María enfrenta el dolor de perder a su hijo, Judas convierte su frustración en traición y el miedo pone a prueba la lealtad de sus discípulos. Desde su entrada triunfal hasta la crucifixión y el descubrimiento de la tumba vacía, La Última Semana de Jesús ofrece una mirada íntima y profundamente humana a los días que transformaron para siempre la historia de la humanidad', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaUltimaSemanaDeJesus/Es/UltimaSemanaJesus_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaUltimaSemanaDeJesus/Es/UltimaSemanaJesus_1440x900.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-american-doctor', 'FICM American Doctor', 'ficm-american-doctor', 'B', 'DOCUMENTAL', 93, 'Tres médicos estadounidenses de origen palestino, judío y zoroastriano entran en Gaza para salvar vidas, y se ven envueltos en conflictos médicos y políticos mientras lo arriesgan todo para revelar la verdad.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMAmericanDoctor/Es/american_doctor.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMAmericanDoctor/Es/1440x900_2__1.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('mary-y-max', 'Mary Y Max', 'mary-y-max', 'B', 'DRAMA', 92, 'Una historia de amistad entre dos personas totalmente distintas: Mary una pequeña y solitaria niña de ocho años, que vive en los suburbios de Melbourne, Australia, y Max, un hombre de cuarenta y cuatro años, también solitario, que vive en Nueva York, Estados Unidos. La primera película de Adam Elliot, ganador del Oscar y director de ''Memorias de un Caracol'', llega por primera vez a los cines de México.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MaryYMax/Es/P_ster_720x1022px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MaryYMax/Es/Header_Movie_details_1440x900px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MaryYMax/Es/6a7cf92d3af60-maryandmax.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-chicas-tristes', 'FICM Chicas Tristes', 'ficm-chicas-tristes', 'B', 'DRAMA', 91, 'Paula y la Maestra son inseparables y las nadadoras más fuertes de su equipo, hasta que un incidente en una fiesta las obliga a elegir entre guardar silencio y hablar, poniendo a prueba su amistad.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMChicasTristes/Es/chicas_tristes_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMChicasTristes/Es/1440x900_copia_10.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-a-long-winter', 'FICM A Long Winter', 'ficm-a-long-winter', 'C', 'DRAMA', 117, 'Tras la desaparición de su madre durante la primera tormenta de nieve de la temporada, un joven se niega a perder la esperanza mientras un largo invierno en Montana transforma su relación con su padre y su comprensión del hombre en que se está convirtiendo.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMALongWinter/Es/a_long_winter.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMALongWinter/Es/1440x900_2__1.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('tadeo-el-explorador-y-la-lampara-maravillosa', 'Tadeo El Explorador Y La Lámpara Maravillosa', 'tadeo-el-explorador-y-la-lampara-maravillosa', 'AA', 'ANIMACIÓN, FAMILIAR', 94, 'Tadeo y Sara son ahora padres de Olimpia (Oli), una adorable e intrépida niña de dos años. Y Momia no lleva nada bien haber dejado de ser el centro de atención. Mientras están de vacaciones en Londres, Sara sigue la pista de un objeto único: la lámpara maravillosa de Las mil y una noches. Y Momia, lleno de celos, pide un deseo: viajar en el tiempo hasta el momento en que era joven y todos le querían. Tadeo y Sara tienen que unir fuerzas para evitar que Momia cambie el curso de la historia y traer al grupo (Jeff, Belzoni y Ramona incluidos) de vuelta a casa. Esta nueva aventura los llevará a cruzar el Océano Atlántico desde la mítica ciudad perdida de Paititi hasta Grecia, y de allí a lo más profundo de Oriente Medio, hasta la misma cueva de Ali Babá y los Cuarenta ladrones.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TadeoElExploradorYLaLamparaMaravillosa/Es/tj4_de_1_6_720x1022_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TadeoElExploradorYLaLamparaMaravillosa/Es/tj4_de_1_2_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TadeoElExploradorYLaLamparaMaravillosa/Es/6a4d6b1d28bec-tadeo-lampara-maravillosa.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-shana', 'FICM Shana', 'ficm-shana', 'C', 'DRAMA', 84, 'Shana afronta los altibajos de la vida cotidiana con una energía inagotable y el apoyo de su grupo de amigos. Cuando su abuela fallece, ella hereda un anillo que, según se dice, la protege del mal de ojo. Sin duda, Shana necesita esa ayuda, sobre todo porque su pareja tóxica ha salido de prisión y las desgracias se acumulan.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMShana/Es/720x1022_copia_2__7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMShana/Es/1440x900_copia_12.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('pinocho-el-lado-oscuro', 'Pinocho: El Lado Oscuro', 'pinocho-el-lado-oscuro', 'C', 'TERROR', 82, 'La película es la quinta entrega de “Twisted Childhood Universe”. La historia sigue a James, un chico que atraviesa un duelo y a quien su abuelo Geppetto le regala una extraña marioneta llamada Pinocho. Influenciado por un siniestro Pepe Grillo (con la voz de Robert Englund) Pinocho emprende una violenta ola de asesinatos para eliminar todo lo “malo” y transformarse en un niño humano de verdad, pieza a pieza.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PinochoElLadoOscuro/Es/PINOCCHIO_UNSTRUNG_poster_720X1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PinochoElLadoOscuro/Es/PINOCCHIO_UNSTRUNG_header_movie_details_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PinochoElLadoOscuro/Es/6a86662e138f6-pinocho-el-lado-oscuro.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-la-bola-negra', 'FICM La Bola Negra', 'ficm-la-bola-negra', 'B15', 'ROMANCE, DRAMA', 155, 'Esta cinta narra las historias entrelazadas de tres hombres en tres épocas diferentes, tres vidas íntimamente unidas por la sexualidad yel deseo, el dolor y la herencia. La película parte de La bola negra, obra que Federico García Lorca dejó inconclusa al ser asesinado en 1936.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMLaBolaNegra/Es/la_bola_negra_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMLaBolaNegra/Es/1440x900_60.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-le-corset', 'FICM Le Corset', 'ficm-le-corset', 'C', 'ANIMACIÓN, DRAMA', 90, 'Christophe, de 11 años, intenta estar a la altura de su padre en la granja familiar. Pero el niño empieza a inclinarse y desplomarse en el tractor, la escuela, la cena... Un médico encuentra la solución: Christophe debe usar un corsé de hierro para mantenerse erguido. Obligado a reinventar su vida lejos de la granja, Christophe descubre su pasión por la música, conoce a una nueva amiga y la sigue en sus travesuras.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMLeCorset/Es/le_corset.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMLeCorset/Es/1440x900_60.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-el-jardin-que-sonamos', 'FICM El Jardín que Soñamos', 'ficm-el-jardin-que-sonamos', 'B', 'DRAMA', 102, 'Esther, Junior, Flor y Aisha, una familia haitiana, viajan al norte del continente americano con la esperanza de un futuro mejor. En el centro de México, se encuentran con el peligroso mundo de la tala ilegal. Mientras Junior lidia con el dolor de su pasado y su nueva vida, Esther arriesga todo para proteger a sus hijas. La migración de las mariposas monarca se convierte en un símbolo de esperanza y resiliencia hacia un nuevo comienzo.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMElJardinqueSonamos/Es/el_jardin_sonamos_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMElJardinqueSonamos/Es/1440x900_copia_10.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('puella-magi-madoka-magica-the-movie', 'Puella Magi Madoka Magica: Walpurgisnacht Rising', 'puella-magi-madoka-magica-the-movie', 'A', 'ANIMACIÓN', 120, '¡La Noche de Walpurgis está aquí! La secuela de Madoka Magica Rebellion. El inicio de un nuevo capitulo. Por Akiyuki Shimbou x Gen Urobuchi (Nitroplus) x aokiume x SHAFT. Entre las chicas de Mitakihara, últimamente circula cierto rumor: el misterioso “teléfono del señor Lagarto” puede cumplir cualquier deseo a cambio de pelear contra las maldiciones del mundo. En ese momento, “chicas sin Gema del Alma” comienzan a cazar a los Espectros y una serie de eventos extraños ocurre. Homura contempla con calma este mundo, teniendo el control de las cosas en su papel de “Demonio”… o así debía de ser. De pronto, algo apareció para poner fin a esa vida distorsionada: el lugar en el que todas las Brujas nacen, Nazukasokotsune; Walpurgisnacht, un conglomerado de Brujas que alguna vez atormentó a Homura y dos Chicas Mágicas desconocidas que están en busca de la Ley de los Ciclos y que dijeron “jamás perdonaremos a Homura Akemi”. En un mundo que ha perdido la Ley de los Ciclos, el destino de las Chicas Mágicas vuelve a girar.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PuellaMagiMadokaMagicaWalpurgisnach/Es/Poster_WEB_Desktop_720x1022px_36_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PuellaMagiMadokaMagicaWalpurgisnach/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_34__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PuellaMagiMadokaMagicaWalpurgisnach/Es/6aa87865917fe-madoka-magica.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
