INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('la-isla-olvidada', 'La Isla Olvidada', 'la-isla-olvidada', 'A', 'COMEDIA, ANIMACIÓN, AVENTURA', 109, 'Dos mejores amigos se quedan varados en el místico mundo de Nakali, donde su único escape podría costarles su vida compartida de recuerdos.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaIslaOlvidada/Es/20_P_ster_720x1022px__5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaIslaOlvidada/Es/5_Header_movie_details_1440x900px_1__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaIslaOlvidada/Es/6a1f26892eb3d-la-isla-olvidada.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-cobarde', 'FICM Cobarde', 'ficm-cobarde', 'C', 'DRAMA', 127, 'Mientras la Primera Guerra Mundial se prolonga, Pierre, un soldado recién llegado al frente, ansía demostrar su valía. Tras las líneas del frente, conoce a Francis, quien decide levantar el ánimo de sus compañeros organizando una obra de teatro. Mientras la violencia continúa, ambos intentan encontrar maneras de escapar de la brutalidad de la guerra, aunque sea por un instante.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMCobarde/Es/cobarde.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMCobarde/Es/1440x900_60.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-como-fui-a-enamorarme-de-ti', 'FICM Cómo Fui a Enamorarme de Ti', 'ficm-como-fui-a-enamorarme-de-ti', 'A', 'COMEDIA, DRAMA', 107, 'Los Bukis, la banda musical del momento, inician una gira por México a principios de los noventa. Durante esta, Marco Antonio, líder y vocalista, es atraído por una misteriosa y provocativa mujer, quien esconde una oscura intención. Los Bukis llevarán sus canciones al público, revelarán sus inicios y su camino al estrellato mientras sin saberlo afrontan el reto de salvar su música ante la amenaza de un empresario que pretende robarla.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMComoFuiaEnamorarmedeTi/Es/como_fui_enamorarme_copia_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMComoFuiaEnamorarmedeTi/Es/1440x900_copia_12.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-un-amor-posible', 'FICM Un Amor Posible', 'ficm-un-amor-posible', 'C', 'ROMANCE, DRAMA', 164, 'Historia de dos parejas (un trabajador despedido y su esposa, y una documentalista y su marido) cuyos caminos se cruzan durante el rodaje de un documental, lo que los enfrenta a sus vidas diferentes y deseos ocultos.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMUnAmorPosible/Es/720x1022_copia_7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMUnAmorPosible/Es/1440x900_copia_12.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-jaripeo', 'FICM Jaripeo', 'ficm-jaripeo', 'B15', 'DOCUMENTAL', 71, 'Un documental híbrido que nos lleva a los rodeos hipermasculinos de Michoacán. Lo que comienza como una celebración de la tradición se adentra en el subconsciente de la memoria, el deseo queer y la añoranza. Un ajuste de cuentas con las heridas y la belleza de un hogar abandonado.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMJaripeo/Es/jaripeo_copia_2__1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMJaripeo/Es/1440x900_copia_10.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-sanguine', 'FICM Sanguine', 'ficm-sanguine', 'C', 'TERROR', 103, 'Margot, una joven interna en la sala de urgencias más competitiva del país, tiene dificultades para adaptarse a este entorno estresante. A medida que atiende a varios pacientes de su edad con síntomas inusuales, su propio cuerpo comienza a mostrar cambios preocupantes.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMSanguine/Es/720x1022_copia_2__7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMSanguine/Es/1440x900_copia_2__12.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-rose', 'FICM Rose', 'ficm-rose', 'C', 'DRAMA', 94, 'A principios del XVII, en Alemania, un misterioso soldado llega a una aislada aldea protestante. El desconocido, con el rostro marcado por una cicatriz, afirma ser heredero de una granja abandonada hace mucho y presenta un documento para respaldar su reclamación ante los recelosos habitantes. Con el tiempo, logra disipar sus dudas y se integra a la comunidad. Sin embargo, su búsqueda de aceptación se cimenta sobre una mentira.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMRose/Es/720x1022_copia_2__7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMRose/Es/1440x900_copia_2__12.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-ray-gunn', 'FICM Ray Gunn', 'ficm-ray-gunn', 'C', 'ANIMACIÓN', 120, 'En un 1939 alternativo, en la gigantesca y futurista ciudad de Metropia —un mundo corrupto donde los alienígenas son la especie dominante—, Ray Gunn, un detective privado venido a menos, investiga un asesinato. Pero no todo es lo que parece.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMRayGunn/Es/ray_gunn.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMRayGunn/Es/1440x900_2__1.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-the-roses-of-marrakech', 'FICM The Roses of Marrakech', 'ficm-the-roses-of-marrakech', 'A', 'DRAMA', 95, 'Leila es la dedicada ama de llaves de madame Isabelle, propietaria de una lujosa finca en Marrakech. Leila mantiene el orden meticuloso de esta burbuja perfecta pero, cuando alguien de su pasado llega inesperadamente, la tranquilidad de este microcosmos empieza a resquebrajarse.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMTheRosesofMarrakech/Es/720x1022_copia_7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMTheRosesofMarrakech/Es/1440x900_66.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-birds-of-war', 'FICM Birds of War', 'ficm-birds-of-war', 'C', 'DOCUMENTAL', 85, 'Este documental profundiza en los archivos personales —que abarcan 13 años— de una periodista libanesa radicada en Londres y de un camarógrafo sirio para narrar la liberación de Alepo y el levantamiento popular en Beirut. A través del intercambio de mensajes de texto y voz, la historia de la guerra se transforma gradualmente en una historia de amor.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMBirdsofWar/Es/birds_war.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMBirdsofWar/Es/1440x900_2__1.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-monstruo-gentil', 'FICM Monstruo Gentil', 'ficm-monstruo-gentil', 'C', 'DRAMA', 115, 'Lucy, pianista de conciertos, acaba de mudarse con su familia de la ciudad a una casa de campo con la esperanza de aliviar el grave agotamiento de Philip, su esposo. Antes de que puedan instalarse en su nuevo hogar, una visita policial al amanecer destroza sus vidas. Aislada y desesperada por proteger a su pequeño hijo, Lucy debe afrontar la situación sola, atrapada entre el hombre que ama y el miedo a lo que pueda haber hecho.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMMonstruoGentil/Es/monstruo_gentil.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMMonstruoGentil/Es/1440x900_2__1.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-a-girl-unknown', 'FICM A Girl Unknown', 'ficm-a-girl-unknown', 'C', 'DRAMA', 125, 'Una niña china vive desde los 6 hasta los 18 años con tres familias distintas, cada una de las cuales le da un nombre y una vida diferentes. Mientras busca un lugar al cual pertenecer y la posibilidad de encontrar el amor, debe afrontar el peso de su pasado y la incertidumbre de su futuro, hasta que finalmente encuentra su propio camino.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMAGirlUnknown/Es/a_girl_unknown_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMAGirlUnknown/Es/1440x900_copia_12.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-look-back-una-pelicula-de-koreeda', 'FICM Look Back. Una película de Kore-eda', 'ficm-look-back-una-pelicula-de-koreeda', 'C', 'DRAMA', 100, 'Fujino, una niña de cuarto grado, crea cómics para el periódico escolar. Todo cambia cuando le piden compartir espacio con Kyomoto, una joven cuyo arte supera cualquier cosa que ella pueda hacer. Ambas se ven envueltas en una pasión por el dibujo que las lleva a la adultez como aspirantes a dibujantes de manga. Ya adultas, Fujino y Kyomoto se embarcan en un viaje donde la alegría de la expresión artística choca con la imprevisibilidad de la vida.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMLookBackUnapeliculadeKoreeda/Es/720x1022_copia_7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMLookBackUnapeliculadeKoreeda/Es/1440x900_60.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-la-venus-electrica', 'FICM La Venus Eléctrica', 'ficm-la-venus-electrica', 'B', 'COMEDIA, ROMANCE', 124, 'París, 1928. Antoine Balestro, un pintor joven y a la moda, no ha podido trabajar desde la muerte de su esposa, para desesperación de su galerista, Armand. Una noche, borracho, Antoine intenta contactar a su esposa mediante una adivina, pero en realidad está hablando con Suzanne, una trabajadora de circo que demuestra ser una impostora con mucho talento, y, junto con Armand, comienza una serie de falsas sesiones de espiritismo.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMLaVenusElectrica/Es/720x1022_copia_2__7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMLaVenusElectrica/Es/1440x900_copia_2__12.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ficm-behemoth-una-vida-en-piezas', 'FICM ¡Behemoth! Una vida. En piezas.', 'ficm-behemoth-una-vida-en-piezas', 'A', 'DRAMA', 124, 'Alex Serian, un talentoso violonchelista, regresa a su hogar en Los Ángeles tras veinte años de vida itinerante. La música, ese ríoconstante y absorbente que ha marcado su existencia, comienza a llevar a Alex hacia una aventura que lo transformará para siempre.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMBehemothUnaVidaEnPiezas/Es/behemoth.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FICMBehemothUnaVidaEnPiezas/Es/1440x900_52.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033265', 'Ozzy & Black Sabbath: Back To The Beginning', 'ozzy-black-sabbath-back-to-the-beginning', 'A', 'DOCUMENTAL', 147, 'En julio de 2025, los padrinos del heavy metal ofrecieron su último concierto en su querido Villa Park de Birmingham, reuniendo a generaciones de artistas a los que inspiraron para un homenaje irrepetible. Junto a la triunfal actuación final de Black Sabbath, la película cuenta con la participación de músicos influenciados por la banda, entre ellos Metallica, Guns N’ Roses, Slayer, Tool, Pantera, Yungblud y Papa (Ghost). Una despedida hístórica y emotiva a Ozzy y a la banda que cambió la música para siempre.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/OzzyBlackSabbathBackToTheBeginning/Es/720x1022_25.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/OzzyBlackSabbathBackToTheBeginning/Es/1440x990_7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/OzzyBlackSabbathBackToTheBeginning/Es/6ab5d2d002934-back-beginning.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
